<script setup>
import {computed,onMounted,ref} from 'vue'; import PageShell from '../components/PageShell.vue'; import MovieCard from '../components/MovieCard.vue'; import StatusPanel from '../components/StatusPanel.vue'; import {useMovieStore} from '../stores/movie'
const store=useMovieStore(),keyword=ref(''),type=ref('全部'),sort=ref('rating'); const load=()=>store.loadMovies(true).catch(()=>{}); onMounted(()=>store.loadMovies().catch(()=>{}))
const types=computed(()=>['全部',...new Set(store.movies.flatMap(m=>String(m.typelist).split(/[,|/]/).map(x=>x.trim()).filter(Boolean)))].slice(0,15));
const shown=computed(()=>store.movies.filter(m=>(!keyword.value||`${m.moviename} ${m.director}`.toLowerCase().includes(keyword.value.toLowerCase()))&&(type.value==='全部'||String(m.typelist).includes(type.value))).sort((a,b)=>sort.value==='hot'?b.numrating-a.numrating:b.averating-a.averating))
const hero=computed(()=>store.movies.find(m=>m.picture&&m.description)||store.movies[0])
</script>
<template><PageShell><section class="hero" :style="hero?.picture?{'--hero':`url(${hero.picture})`}:{}"><div class="hero-content"><div class="eyebrow">本周精选 · EDITOR'S CHOICE</div><h1>{{hero?.moviename||'每一部电影，都是另一种人生'}}</h1><p>{{hero?.description||'探索高分佳作，发现属于你的光影世界。'}}</p><RouterLink v-if="hero" class="primary-button" :to="`/movie/${hero.movieid}`">▶ 查看详情</RouterLink></div></section><section class="content-section"><div class="section-heading"><div><span class="eyebrow">EXPLORE</span><h2>发现好电影</h2></div><div class="controls"><div class="search">⌕<input v-model="keyword" placeholder="搜索电影或导演"></div><select v-model="sort"><option value="rating">评分优先</option><option value="hot">热度优先</option></select></div></div><div class="type-tabs"><button v-for="item in types" :key="item" :class="{active:type===item}" @click="type=item">{{item}}</button></div><div v-if="store.loading" class="movie-grid"><div v-for="n in 8" :key="n" class="skeleton"></div></div><StatusPanel v-else-if="store.error" icon="!" title="电影加载失败" :text="store.error" action="重新加载" @action="load"/><StatusPanel v-else-if="!shown.length" icon="⌕" title="没有找到相关电影" text="换个关键词或分类试试看" action="清除筛选" @action="keyword='';type='全部'"/><div v-else class="movie-grid"><MovieCard v-for="(movie,i) in shown" :key="movie.movieid" :movie="movie" :index="i"/></div></section></PageShell></template>
